Here is the commit message:
ocfs2: handle invalid dinode in ocfs2_group_extend

[BUG]
kernel BUG at fs/ocfs2/resize.c:308!
Oops: invalid opcode: 0000 [#1] SMP KASAN NOPTI
RIP: 0010:ocfs2_group_extend+0x10aa/0x1ae0 fs/ocfs2/resize.c:308
Code: 8b8520ff ffff83f8 860f8580 030000e8 5cc3c1fe
Call Trace:
 ...
 ocfs2_ioctl+0x175/0x6e0 fs/ocfs2/ioctl.c:869
 vfs_ioctl fs/ioctl.c:51 [inline]
 __do_sys_ioctl fs/ioctl.c:597 [inline]
 __se_sys_ioctl fs/ioctl.c:583 [inline]
 __x64_sys_ioctl+0x197/0x1e0 fs/ioctl.c:583
 x64_sys_call+0x1144/0x26a0 arch/x86/include/generated/asm/syscalls_64.h:17
 do_syscall_x64 arch/x86/entry/syscall_64.c:63 [inline]
 do_syscall_64+0x93/0xf80 arch/x86/entry/syscall_64.c:94
 entry_SYSCALL_64_after_hwframe+0x76/0x7e
 ...

[CAUSE]
ocfs2_group_extend() assumes that the global bitmap inode block
returned from ocfs2_inode_lock() has already been validated and
BUG_ONs when the signature is not a dinode. That assumption is too
strong for crafted filesystems because the JBD2-managed buffer path
can bypass structural validation and return an invalid dinode to the
resize ioctl.

[FIX]
Validate the dinode explicitly in ocfs2_group_extend(). If the global
bitmap buffer does not contain a valid dinode, report filesystem
corruption with ocfs2_error() and fail the resize operation instead of
crashing the kernel.

Link: https://lkml.kernel.org/r/20260401092303.3709187-1-gality369@gmail.com
Fixes: 10995aa2451a ("ocfs2: Morph the haphazard OCFS2_IS_VALID_DINODE() checks.")
Signed-off-by: ZhengYuan Huang <gality369@gmail.com>
Reviewed-by: Joseph Qi <joseph.qi@linux.alibaba.com>
Cc: Mark Fasheh <mark@fasheh.com>
Cc: Joel Becker <jlbec@evilplan.org>
Cc: Junxiao Bi <junxiao.bi@oracle.com>
Cc: Changwei Ge <gechangwei@live.cn>
Cc: Jun Piao <piaojun@huawei.com>
Cc: Heming Zhao <heming.zhao@suse.com>
Cc: <stable@vger.kernel.org>
Signed-off-by: Andrew Morton <akpm@linux-foundation.org>

Here is the root cause:
The function ocfs2_group_extend() assumes without proper validation that the global bitmap inode block obtained from ocfs2_inode_lock() contains a valid dinode, and uses BUG_ON to crash the kernel when it does not. This assumption is not safe because JBD2-managed buffer path can bypass structural validation, allowing an invalid dinode to be passed to the resize ioctl, leading to a kernel BUG. The fix replaces the BUG_ON with an explicit validation that returns an error gracefully.

Here is the patch:
  */
 int ocfs2_group_extend(struct inode * inode, int new_clusters)
 {
 	int ret;
 	handle_t *handle;
 	struct buffer_head *main_bm_bh = NULL;
 	struct buffer_head *group_bh = NULL;
 	struct inode *main_bm_inode = NULL;
 	struct ocfs2_dinode *fe = NULL;
 	struct ocfs2_group_desc *group = NULL;
 	struct ocfs2_super *osb = OCFS2_SB(inode->i_sb);
 	u16 cl_bpc;
 	u32 first_new_cluster;
 	u64 lgd_blkno;

 	if (unlikely(ocfs2_emergency_state(osb)))
 		return -EROFS;

 	if (new_clusters < 0)
 		return -EINVAL;
 	else if (new_clusters == 0)
 		return 0;

 	main_bm_inode = ocfs2_get_system_file_inode(osb,
 						    GLOBAL_BITMAP_SYSTEM_INODE,
 						    OCFS2_INVALID_SLOT);
 	if (!main_bm_inode) {
 		ret = -EINVAL;
 		mlog_errno(ret);
 		goto out;
 	}

 	inode_lock(main_bm_inode);

 	ret = ocfs2_inode_lock(main_bm_inode, &main_bm_bh, 1);
 	if (ret < 0) {
 		mlog_errno(ret);
 		goto out_mutex;
 	}

 	fe = (struct ocfs2_dinode *)main_bm_bh->b_data;

-	/* main_bm_bh is validated by inode read inside ocfs2_inode_lock(),
-	 * so any corruption is a code bug. */
-	BUG_ON(!OCFS2_IS_VALID_DINODE(fe));
+	/* JBD-managed buffers can bypass validation, so treat this as corruption. */
+	if (!OCFS2_IS_VALID_DINODE(fe)) {
+		ret = ocfs2_error(main_bm_inode->i_sb,
+				  "Invalid dinode #%llu\n",
+				  (unsigned long long)OCFS2_I(main_bm_inode)->ip_blkno);
+		goto out_unlock;
+	}

 	if (le16_to_cpu(fe->id2.i_chain.cl_cpg) !=
 		ocfs2_group_bitmap_size(osb->sb, 0,
 					osb->s_feature_incompat) * 8) {
 		mlog(ML_ERROR, "The disk is too old and small. "
 		     "Force to do offline resize.");
 		ret = -EINVAL;
 		goto out_unlock;
 	}

 	first_new_cluster = le32_to_cpu(fe->i_clusters);
 	lgd_blkno = ocfs2_which_cluster_group(main_bm_inode,
 					      first_new_cluster - 1);

 	ret = ocfs2_read_group_descriptor(main_bm_inode, fe, lgd_blkno,
 					  &group_bh);
 	if (ret < 0) {
 		mlog_errno(ret);
 		goto out_unlock;
 	}
 	group = (struct ocfs2_group_desc *)group_bh->b_data;

 	cl_bpc = le16_to_cpu(fe->id2.i_chain.cl_bpc);
 	if (le16_to_cpu(group->bg_bits) / cl_bpc + new_clusters >
 		le16_to_cpu(fe->id2.i_chain.cl_cpg)) {
 		ret = -EINVAL;
 		goto out_unlock;
 	}


 	trace_ocfs2_group_extend(
 	     (unsigned long long)le64_to_cpu(group->bg_blkno), new_clusters);

 	handle = ocfs2_start_trans(osb, OCFS2_GROUP_EXTEND_CREDITS);
 	if (IS_ERR(handle)) {
 		mlog_errno(PTR_ERR(handle));
 		ret = -EINVAL;
 		goto out_unlock;
 	}

 	/* update the last group descriptor and inode. */
 	ret = ocfs2_update_last_group_and_inode(handle, main_bm_inode,
 						main_bm_bh, group_bh,
 						first_new_cluster,
 						new_clusters);
 	if (ret) {
 		mlog_errno(ret);
 		goto out_commit;
 	}

 	ocfs2_update_super_and_backups(main_bm_inode, new_clusters);

 out_commit:
 	ocfs2_commit_trans(osb, handle);
 out_unlock:
 	brelse(group_bh);
 	brelse(main_bm_bh);

 	ocfs2_inode_unlock(main_bm_inode, 1);

 out_mutex:
 	inode_unlock(main_bm_inode);
 	iput(main_bm_inode);

 out:
 	return ret;
 }



